const r=String.raw;
const questions=[];
const lessons={mono:'Bài 1 · Tính đơn điệu và cực trị',ext:'Bài 2 · Giá trị lớn nhất, nhỏ nhất',asym:'Bài 3 · Đường tiệm cận',tangent:'Bài 4 · Khảo sát và tiếp tuyến',opt:'Bài 5 · Ứng dụng và tối ưu hóa'};
const packs={
 mono:[r`f'(x)>0\Rightarrow f\text{ đồng biến};\quad f'(x)<0\Rightarrow f\text{ nghịch biến}`,r`f'\text{ đổi dấu tại }x_0\Rightarrow x_0\text{ là điểm cực trị}`],
 ext:[r`\text{So sánh }f(a),\ f(b),\ f(x_i)\text{ với }x_i\in(a;b),\ f'(x_i)=0`],
 asym:[r`\lim_{x\to x_0^\pm}f(x)=\pm\infty\Rightarrow x=x_0\text{ là TCĐ}`,r`\lim_{x\to\pm\infty}f(x)=L\Rightarrow y=L\text{ là TCN}`,r`\lim_{x\to\pm\infty}[f(x)-(ax+b)]=0\Rightarrow y=ax+b\text{ là TCX}`],
 tangent:[r`y=f'(x_0)(x-x_0)+f(x_0)`,r`\left(\frac uv\right)'=\frac{u'v-uv'}{v^2}`],
 opt:[r`F'(x)=0\quad\text{tại điểm cực trị trong miền xác định}`,r`\text{Kiểm tra dấu đạo hàm, các đầu mút và điều kiện thực tế}`]
};
function add(n,type,prompt,options,answer,steps,extra={}){
 const guide={formulas:packs[type],symbols:[[r`x,x_0`,'Biến số và giá trị đang xét.'],[r`f,F`,'Hàm số của bài toán.']],condition:''};
 const solutionSteps=steps.map((content,i)=>typeof content==='string'?{title:'',content}:content);
 questions.push({id:`toan-12-1-pdf-${n}-v1`,source:{file:'Chuong_1.pdf',item:String(n)},sourceNumber:n,lesson:lessons[type],type:({mono:'Đơn điệu và cực trị',ext:'Giá trị lớn nhất, nhỏ nhất',asym:'Tiệm cận',tangent:'Đồ thị và tiếp tuyến',opt:'Ứng dụng đạo hàm'})[type],kind:'choice',prompt,options,answer,guide,solutionSteps,explanation:solutionSteps.map(s=>s.content).join(' '),hint:'Xem công thức và lời giải từng bước.',difficulty:type==='opt'?'Vận dụng':'Thông hiểu',sample:false,nativeLatex:true,...extra});
}
const mc=add;
mc(1,'asym',r`Cho hàm số \(y=\frac{ax+b}{cx+d}\), \(ac\ne0,\ ad-bc\ne0\), có bảng biến thiên như hình. Đường tiệm cận đứng có phương trình nào?`,[r`\(y=-2\)`,r`\(x=-2\)`,r`\(y=1\)`,r`\(x=1\)`],1,[r`Từ bảng biến thiên, điểm gián đoạn cần xét là \(x=-2\).`,r`Đọc giới hạn: \(\lim_{x\to-2^-}f(x)=-\infty\), \(\lim_{x\to-2^+}f(x)=+\infty\).`,r`Giới hạn một phía vô cực nên đường tiệm cận đứng là \(x=-2\).`]);
mc(2,'asym',r`Cho \(y=\frac{ax+b}{cx+d}\), \(ac\ne0,\ ad-bc\ne0\), có đồ thị như hình. Trong bốn hệ số \(a,b,c,d\), có bao nhiêu số dương?`,['2','1','3','0'],0,[r`Tiệm cận đứng \(x=1\) cho \(-d/c=1\), nên \(c,d\) trái dấu. Tiệm cận ngang \(y=-1\) cho \(a/c=-1\), nên \(a,c\) trái dấu.`,r`Đồ thị đi qua \((0;-2)\), nên \(b/d=-2\): \(b,d\) trái dấu. Nếu \(c>0\), suy ra \(d<0,a<0,b>0\); có hai số dương là \(b,c\).`,r`Nếu \(c<0\), tất cả dấu đảo lại: \(a,d>0\), \(b,c<0\). Trong cả hai trường hợp có đúng 2 số dương.`]);
mc(3,'asym',r`Tiệm cận đứng của đồ thị \(y=\frac{2x-2}{x+1}\) là:`,[r`\(x=-1\)`,r`\(x=1\)`,r`\(x=-2\)`,r`\(x=2\)`],0,[r`Điều kiện xác định: \(x+1\ne0\), tức \(x\ne-1\).`,r`Tại \(x=-1\), tử số bằng \(2(-1)-2=-4\ne0\), nên không có khử nhân tử gây mất tiệm cận.`,r`Mẫu tiến về 0 còn tử khác 0, nên giới hạn một phía vô cực. Tiệm cận đứng là \(x=-1\).`]);
mc(4,'mono',r`Cho hàm số \(f(x)=ax^3+bx^2+cx+d\) có đồ thị như hình. Giá trị cực tiểu là:`,[r`\(N(0;-1)\)`,r`\(y=-1\)`,r`\(x=0\)`,r`\(x=-1\)`],1,[r`Điểm thấp nhất cục bộ trên đồ thị là \((0;-1)\).`,r`Hoành độ cực tiểu là \(x=0\); giá trị cực tiểu là tung độ \(f(0)=-1\).`,r`Đề hỏi giá trị, nên chọn \(y=-1\).`]);
mc(5,'mono',r`Hàm số nào sau đây đồng biến trên \(\mathbb R\)?`,[r`\(y=3^{-x}\)`,r`\(y=2026^x\)`,r`\(y=\frac{2x-1}{x-1}\)`,r`\(y=\log_2x\)`],1,[r`\(3^{-x}=(1/3)^x\) có cơ số nhỏ hơn 1 nên nghịch biến. Hàm phân thức không xác định tại 1; hàm logarit chỉ xác định khi \(x>0\).`,r`Hàm \(y=2026^x\) có tập xác định \(\mathbb R\) và \(y'=2026^x\ln2026>0\).`,r`Vậy \(y=2026^x\) đồng biến trên toàn bộ \(\mathbb R\).`]);
mc(6,'asym',r`Đường tiệm cận ngang của \(y=\frac{x+3}{2x-4}\) là:`,[r`\(x=\frac12\)`,r`\(y=2\)`,r`\(y=\frac12\)`,r`\(x=2\)`],2,[r`Chia tử và mẫu cho \(x\): \(y=\frac{1+3/x}{2-4/x}\).`,r`Khi \(x\to\pm\infty\), hai số \(3/x,4/x\) tiến về 0, nên \(y\to1/2\).`,r`Đường tiệm cận ngang là \(y=1/2\).`]);
mc(7,'asym',r`Cho hàm số \(y=\frac{ax+2}{x+c}\) có đồ thị như hình. Tính \(P=a-2c\).`,['5','3','−3','−5'],0,[r`Đọc tiệm cận đứng \(x=2\): \(-c=2\Rightarrow c=-2\).`,r`Đọc tiệm cận ngang \(y=1\): \(a=1\).`,r`Thay số: \(P=1-2(-2)=1+4=5\).`]);
mc(8,'opt',r`Từ tấm bìa hình vuông cạnh 20 cm, cắt bốn hình vuông bằng nhau ở bốn góc rồi gấp thành hộp chữ nhật không nắp như hình. Cạnh hình vuông bị cắt bằng bao nhiêu để thể tích hộp lớn nhất?`,[r`\(\frac{20}3\) cm`,r`\(\frac{10}3\) cm`,'5 cm','4 cm'],1,[r`Gọi cạnh bị cắt là \(x\) cm, \(0<x<10\). Hộp có đáy cạnh \(20-2x\), chiều cao \(x\).`,r`\[V(x)=x(20-2x)^2=4x^3-80x^2+400x.\]`,r`\[V'(x)=12x^2-160x+400=4(3x-10)(x-10).\] Đạo hàm bằng 0 tại \(10/3\) và 10; loại 10 vì hộp suy biến.`,r`Trong miền \((0;10)\), đạo hàm dương trước \(10/3\), âm sau đó. Thể tích lớn nhất tại \(x=10/3\) cm.`]);
mc(9,'mono',r`Cho \(f'(x)=(x-2)(x+1)\) với mọi \(x\in\mathbb R\). Mệnh đề nào đúng?`,[r`Đồng biến trên \((-1;+\infty)\).`,r`Nghịch biến trên \((2;+\infty)\).`,r`Nghịch biến trên \((-1;2)\).`,r`Đồng biến trên \((-1;2)\).`],2,[r`\(f'(x)=0\iff x=-1\) hoặc \(x=2\).`,r`Trên \((-1;2)\), \(x+1>0\), \(x-2<0\) nên \(f'(x)<0\). Ngoài hai nghiệm, đạo hàm dương.`,r`Vậy hàm số nghịch biến trên \((-1;2)\).`]);
mc(10,'tangent',r`Đồ thị \((C):y=\frac{x^2-4x+5}{x-1}\) có hai điểm cực trị. Đường thẳng qua hai điểm đó cắt trục hoành tại \(M\). Hoành độ \(x_M\) là:`,[r`\(2\)`,r`\(1-\sqrt2\)`,r`\(1\)`,r`\(1+\sqrt2\)`],0,[r`Đặt \(u=x^2-4x+5\), \(v=x-1\). Tại điểm cực trị, \(u'v-uv'=0\), mà \(v'=1\), nên \(y=u/v=u'=2x-4\).`,r`Hai điểm cực trị cùng thuộc đường thẳng \(y=2x-4\). Có thể kiểm tra đạo hàm triệt tiêu tại \(x=1\pm\sqrt2\), là hai điểm phân biệt.`,r`Trên trục hoành, \(y_M=0\). Do đó \(2x_M-4=0\Rightarrow x_M=2\).`]);
mc(11,'mono',r`Hàm số \(f\) xác định trên \(\mathbb R\) có bảng biến thiên như hình. Hàm số nghịch biến trên khoảng nào?`,[r`\((-\infty;2)\)`,r`\((6;+\infty)\)`,r`\((2;6)\)`,r`\((-\infty;6)\)`],2,[r`Tìm đoạn mang dấu âm trên hàng \(f'(x)\).`,r`Bảng cho \(f'(x)<0\) khi \(2<x<6\); bên ngoài khoảng này đạo hàm dương.`,r`Khoảng nghịch biến là \((2;6)\).`]);
mc(12,'ext',r`Hàm số \(f\) liên tục trên \([-1;1]\), có đồ thị như hình. Hàm số đạt giá trị lớn nhất tại \(x_0\) bằng:`,[r`\(-2\)`,r`\(2\)`,r`\(-1\)`,r`\(1\)`],3,[r`Chỉ xét phần đồ thị ứng với \(-1\le x\le1\).`,r`Điểm có tung độ lớn nhất trên phần này là \((1;2)\).`,r`Đề hỏi hoành độ đạt max, nên \(x_0=1\), không phải giá trị max bằng 2.`]);
mc(13,'mono',r`Cho hàm số \(f\) có bảng biến thiên như hình. Giá trị cực đại bằng:`,['3','2','−2','−3'],1,[r`Tại \(x=3\), đạo hàm đổi dấu từ dương sang âm.`,r`Vì vậy hàm đạt cực đại tại \(x=3\). Đọc hàng \(f(x)\) được \(f(3)=2\).`,r`Giá trị cực đại bằng 2.`]);
mc(14,'mono',r`Cho \(f'(x)=x+1\) với mọi \(x\in\mathbb R\). Hàm số nghịch biến trên khoảng nào?`,[r`\((-1;+\infty)\)`,r`\((1;+\infty)\)`,r`\((-\infty;-1)\)`,r`\((-\infty;1)\)`],2,[r`Hàm nghịch biến khi đạo hàm âm.`,r`\(f'(x)<0\iff x+1<0\iff x<-1\).`,r`Khoảng cần chọn là \((-\infty;-1)\).`]);
mc(15,'asym',r`Tâm đối xứng của đồ thị \(y=\frac{3x+1}{x-2}\) là:`,[r`\((3;-2)\)`,r`\((3;2)\)`,r`\((-2;3)\)`,r`\((2;3)\)`],3,[r`Chia đa thức: \(y=3+7/(x-2)\).`,r`Hai tiệm cận là \(x=2\), \(y=3\).`,r`Tâm đối xứng là giao điểm hai tiệm cận: \(I(2;3)\).`]);
mc(16,'mono',r`Cho hàm số \(f\) xác định trên \(\mathbb R\), có bảng biến thiên như hình. Hàm số đồng biến trên khoảng nào?`,[r`\((-\infty;-1)\)`,r`\((-2;4)\)`,r`\((2;+\infty)\)`,r`\((-1;2)\)`],3,[r`Tìm dấu dương trên hàng đạo hàm.`,r`Bảng cho \(f'(x)>0\) trên \((-1;2)\), âm ở hai khoảng còn lại.`,r`Hàm đồng biến trên \((-1;2)\).`]);
mc(17,'mono',r`Hàm đa thức bậc ba có bảng biến thiên như hình. Giá trị cực đại bằng:`,[r`\(-2\)`,r`\(2\)`,r`\(-1\)`,r`\(1\)`],1,[r`Đạo hàm đổi từ dương sang âm tại \(x=-1\), nên đây là hoành độ cực đại.`,r`Đọc giá trị hàm tại đó: \(f(-1)=2\).`,r`Giá trị cực đại bằng 2.`]);
mc(18,'asym',r`Tìm tiệm cận xiên của \(y=\frac{3x^2+4x-5}{x-1}\).`,[r`\(y=x-1\)`,r`\(y=3x+3\)`,r`\(y=5x+10\)`,r`\(y=3x+7\)`],3,[r`Chia tử cho mẫu: \(3x^2+4x-5=(x-1)(3x+7)+2\).`,r`\[y=3x+7+\frac2{x-1},\quad\lim_{x\to\pm\infty}\frac2{x-1}=0.\]`,r`Tiệm cận xiên là \(y=3x+7\).`]);
mc(19,'mono',r`Cho hàm số \(f\) có đồ thị như hình. Hàm đồng biến trên khoảng nào?`,[r`\((0;1)\)`,r`\((1;2)\)`,r`\((0;3)\)`,r`\((1;4)\)`],0,[r`Đọc chiều chuyển động của đồ thị từ trái sang phải.`,r`Trên \((0;1)\), đồ thị đi lên; các khoảng còn lại chứa phần đồ thị đi xuống.`,r`Chọn \((0;1)\).`]);
mc(20,'mono',r`Cho hàm số có bảng biến thiên như hình. Hàm nghịch biến trên khoảng nào?`,[r`\((1;2)\)`,r`\((-2;+\infty)\)`,r`\((-1;2)\)`,r`\((-\infty;0)\)`],0,[r`Bảng cho đạo hàm âm trên \((-\infty;-2)\) và \((0;+\infty)\).`,r`Khoảng \((1;2)\) nằm hoàn toàn trong \((0;+\infty)\). Ba khoảng còn lại chứa phần hàm đồng biến.`,r`Vì vậy hàm nghịch biến trên \((1;2)\).`]);
mc(21,'mono',r`Hàm số \(y=\frac{x^2+2x+4}{x+2}\) nghịch biến trên khoảng nào?`,[r`\((-2;0)\)`,r`\((-\infty;-2)\)`,r`\((0;+\infty)\)`,r`\((-4;0)\)`],0,[r`Tập xác định \(D=\mathbb R\setminus\{-2\}\).`,r`\[y'=\frac{(2x+2)(x+2)-(x^2+2x+4)}{(x+2)^2}=\frac{x(x+4)}{(x+2)^2}.\]`,r`Mẫu dương trên tập xác định. Tử âm khi \(-4<x<0\); phải tách tại \(-2\).`,r`Các khoảng nghịch biến là \((-4;-2)\), \((-2;0)\). Chọn \((-2;0)\).`]);
mc(22,'tangent',r`Trong bốn hình A, B, C, D dưới đây, hình nào biểu diễn \(y=\sin x\)?`,['Hình A','Hình B','Hình C','Hình D'],3,[r`Đồ thị sin đi qua \(O(0;0)\), tăng ngay bên phải gốc tọa độ.`,r`Các mốc đặc trưng: \(\sin(\pi/2)=1\), \(\sin(-\pi/2)=-1\), \(\sin(\pm\pi)=0\).`,r`Đối chiếu các mốc và chiều đi của đường cong, hình D phù hợp.`]);
mc(23,'asym',r`Hàm số xác định trên \(\mathbb R\setminus\{-1\}\) có bảng biến thiên như hình. Đồ thị có bao nhiêu tiệm cận ngang?`,['0','2','3','1'],1,[r`Đọc giới hạn ở hai đầu vô cực: \(\lim_{x\to-\infty}f(x)=2\), \(\lim_{x\to+\infty}f(x)=-2\).`,r`Suy ra hai tiệm cận ngang \(y=2\) và \(y=-2\).`,r`Hai đường khác nhau, nên có 2 tiệm cận ngang.`]);
mc(24,'mono',r`Hàm số \(y=ax^3+bx^2+cx+d\) có đồ thị như hình. Hàm đồng biến trên khoảng nào?`,[r`\((-1;2)\)`,r`\((2;+\infty)\)`,r`\((-1;3)\)`,r`\((0;2)\)`],3,[r`Đồ thị có cực tiểu tại hoành độ 0, cực đại tại hoành độ 2.`,r`Giữa hai mốc này, đường cong đi lên từ trái sang phải.`,r`Khoảng đồng biến cần chọn là \((0;2)\).`]);
mc(25,'mono',r`Cho hàm số có đồ thị như hình. Hàm đồng biến trên khoảng nào?`,[r`\((-\infty;-1)\)`,r`\((-\infty;1)\)`,r`\((-1;1)\)`,r`\((1;+\infty)\)`],2,[r`Đồ thị có điểm cực tiểu tại hoành độ −1 và điểm cực đại tại hoành độ 1.`,r`Từ −1 đến 1, đồ thị đi lên; ở hai phía ngoài, đồ thị đi xuống.`,r`Vì vậy chọn \((-1;1)\).`]);
mc(26,'mono',r`Hàm số nào sau đây không có cực trị?`,[r`\(y=\frac{x^2-3}{x-2}\)`,r`\(y=\frac{2x-1}{x+2}\)`,r`\(y=x^3-2x-1\)`,r`\(y=-x^4-x^2+1\)`],1,[r`Với phương án B, điều kiện \(x\ne-2\).`,r`\[y'=\frac{2(x+2)-(2x-1)}{(x+2)^2}=\frac5{(x+2)^2}>0.\]`,r`Đạo hàm không triệt tiêu và không đổi dấu trên mỗi khoảng xác định; −2 không thuộc tập xác định. Hàm B không có cực trị.`]);
mc(27,'mono',r`Cho hàm số \(f\) có đồ thị như hình. Hàm đồng biến trên khoảng nào?`,[r`\((0;+\infty)\)`,r`\((-1;+\infty)\)`,r`\((-2;0)\)`,r`\((-4;+\infty)\)`],0,[r`Đồ thị đi lên trước hoành độ −2 và sau hoành độ 0.`,r`Các khoảng đồng biến là \((-\infty;-2)\) và \((0;+\infty)\).`,r`Trong bốn lựa chọn, chỉ \((0;+\infty)\) nằm trọn trong miền đồng biến.`]);
mc(28,'tangent',r`Đường cong trong hình là đồ thị của hàm số nào?`,[r`\(y=\frac{x^2+x-1}{x-1}\)`,r`\(y=\frac{x^2-x+1}{x-1}\)`,r`\(y=\frac{x^2-4x-1}{x+1}\)`,r`\(y=\frac{x^2-4x+5}{x-2}\)`],1,[r`Tiệm cận đứng trong hình là \(x=1\), nên loại C và D.`,r`Đồ thị đi qua \((0;-1)\). Phương án A cho \(y(0)=1\), phương án B cho \(y(0)=-1\).`,r`Kiểm tra thêm B: \(y=x+1/(x-1)\), có tiệm cận xiên \(y=x\) như hình. Chọn B.`]);
mc(29,'asym',r`Cho \(y=\frac{ax+b}{cx+d}\), \(c\ne0,ad-bc\ne0\), có đồ thị như hình. Tiệm cận ngang là:`,[r`\(x=-1\)`,r`\(y=\frac12\)`,r`\(y=-1\)`,r`\(x=\frac12\)`],1,[r`Tiệm cận ngang phải có dạng \(y=L\), nên loại các đường thẳng đứng.`,r`Ở hai đầu đồ thị, tung độ tiến về mức nằm giữa 0 và 1, được đánh dấu \(1/2\).`,r`Tiệm cận ngang là \(y=1/2\).`]);
mc(30,'ext',r`Tìm giá trị lớn nhất \(M\) của \(y=\frac{3x-1}{x-3}\) trên \([0;2]\).`,['5','−5',r`\(\frac13\)`,r`\(-\frac13\)`],2,[r`Hàm liên tục trên đoạn vì \(3\notin[0;2]\).`,r`\[y'=\frac{3(x-3)-(3x-1)}{(x-3)^2}=-\frac8{(x-3)^2}<0.\]`,r`Hàm nghịch biến, nên max tại đầu trái: \(M=f(0)=(-1)/(-3)=1/3\).`]);
mc(31,'ext',r`Giá trị nhỏ nhất của \(y=\frac{x^2+3}{x-1}\) trên \([2;4]\) bằng:`,['6','−2','−3',r`\(\frac{19}3\)`],0,[r`Hàm liên tục trên đoạn. \[y'=\frac{2x(x-1)-(x^2+3)}{(x-1)^2}=\frac{(x-3)(x+1)}{(x-1)^2}.\]`,r`Trong đoạn chỉ có điểm dừng \(x=3\); nghiệm −1 bị loại.`,r`So sánh \(f(2)=7\), \(f(3)=6\), \(f(4)=19/3\). Giá trị nhỏ nhất bằng 6.`]);
mc(32,'mono',r`Cho \(y=\frac{x-2}{x+3}\). Mệnh đề nào đúng?`,[r`Nghịch biến trên \(\mathbb R\).`,r`Nghịch biến trên từng khoảng \((-\infty;-3)\), \((-3;+\infty)\).`,r`Đồng biến trên từng khoảng \((-\infty;-3)\), \((-3;+\infty)\).`,r`Đồng biến trên \(\mathbb R\).`],2,[r`Tập xác định là \(\mathbb R\setminus\{-3\}\).`,r`\[y'=\frac{x+3-(x-2)}{(x+3)^2}=\frac5{(x+3)^2}>0.\]`,r`Hàm đồng biến trên mỗi khoảng xác định. Không được kết luận đồng biến trên toàn bộ \(\mathbb R\) vì không xác định tại −3.`]);
mc(33,'tangent',r`Một vật có phương trình \(s(t)=3\cos t\). Vận tốc tức thời là:`,[r`\(v(t)=-3\sin t\)`,r`\(v(t)=-3\cos t\)`,r`\(v(t)=3\cos t\)`,r`\(v(t)=3\sin t\)`],0,[r`Vận tốc là đạo hàm của tọa độ theo thời gian: \(v(t)=s'(t)\).`,r`Dùng \((\cos t)'=-\sin t\), giữ nguyên hệ số 3.`,r`Suy ra \(v(t)=-3\sin t\).`]);
mc(34,'mono',r`Cho \(f'(x)=(x-2)(x+1)\) trên \(\mathbb R\). Mệnh đề nào đúng?`,[r`Đồng biến trên \((-1;+\infty)\).`,r`Đồng biến trên \((-\infty;2)\).`,r`Đồng biến trên \((-1;2)\).`,r`Nghịch biến trên \((-1;2)\).`],3,[r`Giải \((x-2)(x+1)=0\) được hai mốc −1 và 2.`,r`Trên \((-1;2)\), hai thừa số trái dấu nên đạo hàm âm. Hai miền bên ngoài có đạo hàm dương.`,r`Hàm nghịch biến trên \((-1;2)\), chọn D.`]);
mc(35,'mono',r`Hàm số liên tục trên \(\mathbb R\), có bảng xét dấu đạo hàm như hình. Hàm số có bao nhiêu điểm cực trị?`,['4','3','2','1'],1,[r`Các nghiệm đạo hàm cần xét là −2, 0 và 2.`,r`Đạo hàm lần lượt đổi dấu \(+\to-\), \(-\to+\), \(+\to-\) khi qua ba mốc.`,r`Cả ba mốc đều là điểm cực trị vì hàm liên tục. Có 3 điểm cực trị.`]);
mc(36,'tangent',r`Hàm số \(f\) có đạo hàm liên tục trên \(\mathbb R\), \(\int_0^2 f'(x)\,dx=45\) và \(f(0)=3\). Tính \(f(2)\).`,['42','15','48','135'],2,[r`Áp dụng Newton–Leibniz: \(\int_0^2 f'(x)\,dx=f(2)-f(0)\).`,r`Thay dữ kiện: \(45=f(2)-3\).`,r`Chuyển vế: \(f(2)=45+3=48\).`]);
mc(37,'mono',r`Cho đồ thị như hình. Hàm số nghịch biến trên khoảng nào?`,[r`\((-\infty;-1)\)`,r`\((2;+\infty)\)`,r`\((-1;2)\)`,r`\((0;2)\)`],3,[r`Đọc phần đồ thị đi xuống từ trái sang phải.`,r`Trong \((0;2)\), hàm giảm từ mức cực đại về cực tiểu. Các khoảng khác không nằm trọn trong phần đi xuống.`,r`Chọn \((0;2)\).`]);
mc(38,'ext',r`Hàm số \(f\) liên tục trên \([1;5]\), có đồ thị như hình. Giá trị lớn nhất đạt tại:`,[r`\(x=1\)`,r`\(x=5\)`,r`\(x=2\)`,r`\(x=4\)`],2,[r`Giới hạn phần đồ thị cần đọc trong \(1\le x\le5\).`,r`Điểm có tung độ lớn nhất là \((2;4)\).`,r`Hoành độ đạt giá trị lớn nhất là \(x=2\).`]);
mc(39,'asym',r`Cho bảng biến thiên như hình. Tiệm cận đứng của đồ thị là:`,[r`\(x=2\)`,r`\(y=2\)`,r`\(x=1\)`,r`\(y=1\)`],2,[r`Tại \(x=1\), bảng có điểm gián đoạn.`,r`\(\lim_{x\to1^-}f(x)=-\infty\), \(\lim_{x\to1^+}f(x)=+\infty\).`,r`Suy ra tiệm cận đứng \(x=1\).`]);
mc(40,'tangent',r`Đồ thị trong hình là đồ thị của hàm số nào?`,[r`\(y=\frac{2x+1}{x-1}\)`,r`\(y=\frac{2x-1}{x-1}\)`,r`\(y=\frac{-x^2+3x+1}{x-1}\)`,r`\(y=\frac{x^2-3x+1}{x-1}\)`],3,[r`Hình có tiệm cận xiên, loại hai phân thức bậc nhất trên bậc nhất A, B.`,r`Tiệm cận xiên có hệ số góc dương. Với D: \(y=x-2-1/(x-1)\), tiệm cận xiên \(y=x-2\). Phương án C có hệ số góc âm.`,r`Kiểm tra \(y(0)=-1\), khớp giao trục tung. Chọn D.`]);
mc(41,'asym',r`Cho bảng biến thiên như hình. Tổng số tiệm cận đứng và ngang của đồ thị là:`,['2','0','1','3'],0,[r`Khi \(x\to-\infty\), hàm tiến về −1 nên có tiệm cận ngang \(y=-1\). Khi \(x\to+\infty\), hàm tiến về \(-\infty\), không có thêm tiệm cận ngang.`,r`Tại \(x=1\), ít nhất một giới hạn một phía vô cực nên có tiệm cận đứng \(x=1\).`,r`Tổng cộng \(1+1=2\) đường.`]);
mc(42,'mono',r`Cho bảng biến thiên như hình. Hàm số đạt cực tiểu tại:`,[r`\(y=0\)`,r`\(x=-4\)`,r`\(y=-4\)`,r`\(x=3\)`],3,[r`Đọc dấu đạo hàm ở hai phía mỗi điểm dừng.`,r`Tại \(x=3\), đạo hàm đổi từ âm sang dương, nên đó là hoành độ cực tiểu.`,r`Chọn \(x=3\); −4 là giá trị cực tiểu, không phải điểm cần hỏi.`]);
mc(43,'asym',r`Đồ thị \(y=f(x)\) như hình có tiệm cận ngang là:`,[r`\(x=-1\)`,r`\(x=1\)`,r`\(y=2\)`,r`\(y=-2\)`],2,[r`Tìm đường nằm ngang mà hai nhánh đồ thị tiến sát ở xa.`,r`Mức đó được đánh dấu \(y=2\).`,r`Tiệm cận ngang là \(y=2\).`]);
mc(44,'mono',r`Cho bảng biến thiên như hình. Hàm số đồng biến trên khoảng nào?`,[r`\((-1;1)\)`,r`\((1;+\infty)\)`,r`\((0;1)\)`,r`\((-1;0)\)`],2,[r`Các khoảng có đạo hàm dương là \((-\infty;-1)\), \((0;1)\).`,r`Trong bốn lựa chọn, \((0;1)\) nằm hoàn toàn trong miền đạo hàm dương.`,r`Chọn \((0;1)\).`]);
mc(45,'tangent',r`Một chất điểm chuyển động theo \(s(t)=2t^2+3t\), với \(t\) tính bằng giây và \(s\) tính bằng mét. Vận tốc tại \(t=2\) bằng:`,['19 m/s','22 m/s','11 m/s','9 m/s'],2,[r`Tính đạo hàm: \(v(t)=s'(t)=4t+3\).`,r`Thay \(t=2\): \(v(2)=4\cdot2+3\).`,r`Suy ra \(v(2)=11\) m/s.`]);
mc(46,'mono',r`Cho \(f(x)=x^3+2x+\cos x\). Phát biểu nào đúng?`,[r`\(f'(x)=3x^2+2+\sin x\).`,r`Hàm đồng biến trên \((-\pi;\pi)\).`,r`Hàm nghịch biến trên \((\pi;2\pi)\).`,r`\(f(2025)>f(2026)\).`],1,[r`Tính đạo hàm đúng: \(f'(x)=3x^2+2-\sin x\).`,r`Vì \(\sin x\le1\), nên \(f'(x)\ge3x^2+1>0\) với mọi số thực.`,r`Hàm đồng biến trên \(\mathbb R\), do đó đồng biến trên \((-\pi;\pi)\). Chọn B.`]);
mc(47,'mono',r`Hàm số \(f\) liên tục trên \(\mathbb R\), có bảng xét dấu đạo hàm như hình. Mệnh đề nào đúng?`,[r`Đồng biến trên \((-2;0)\).`,r`Đồng biến trên \((-\infty;0)\).`,r`Nghịch biến trên \((0;2)\).`,r`Nghịch biến trên \((-\infty;-2)\).`],2,[r`Đọc hàng đạo hàm: dấu âm trên \((-2;0)\) và \((0;2)\); dấu dương ở hai phía ngoài.`,r`Trên \((0;2)\), đạo hàm âm và hàm xác định.`,r`Hàm nghịch biến trên \((0;2)\), chọn C.`]);
mc(48,'tangent',r`Hệ số góc tiếp tuyến với \(y=x\ln x\) tại hoành độ \(x=e\) bằng:`,['1','0','2',r`\(e\)`],2,[r`Với \(x>0\), dùng đạo hàm tích: \((x\ln x)'=\ln x+x(1/x)\).`,r`Rút gọn: \(y'=\ln x+1\).`,r`Hệ số góc \(k=y'(e)=\ln e+1=2\).`]);
mc(49,'mono',r`Hàm số nào nghịch biến trên \(\mathbb R\)?`,[r`\(y=x^3+x\)`,r`\(y=-x^3-3x\)`,r`\(y=-x^4-x^2\)`,r`\(y=\frac{x+1}{x-3}\)`],1,[r`Với B, \(y'=-3x^2-3=-3(x^2+1)<0\) với mọi số thực.`,r`A có đạo hàm \(3x^2+1>0\). C đổi dấu đạo hàm tại 0; D không xác định trên toàn bộ \(\mathbb R\).`,r`Chọn \(y=-x^3-3x\).`]);
mc(50,'ext',r`Hàm số \(f\) liên tục trên \([-2;4]\), có đồ thị như hình. Tổng giá trị lớn nhất và nhỏ nhất trên đoạn bằng:`,['5','−2','3','0'],2,[r`Đọc điểm cao nhất: \(M=f(-2)=7\).`,r`Đọc điểm thấp nhất: \(m=f(4)=-4\).`,r`Cộng hai giá trị: \(M+m=7-4=3\).`]);
mc(51,'ext',r`Giá trị nhỏ nhất của \(f(x)=x^3-3x+2\) trên \([-3;3]\) bằng:`,['0','−16','4','20'],1,[r`\(f'(x)=3x^2-3=3(x-1)(x+1)\). Điểm dừng trong đoạn là \(x=-1,1\).`,r`Tính ở bốn điểm: \(f(-3)=-16\), \(f(-1)=4\), \(f(1)=0\), \(f(3)=20\).`,r`Giá trị nhỏ nhất là −16 tại đầu mút −3.`]);
mc(52,'mono',r`Cho hàm số \(y=ax^3+bx^2+cx+d\) có đồ thị như hình. Giá trị cực đại bằng:`,['1','3','0','−1'],1,[r`Điểm cực đại trên đồ thị có tọa độ \((1;3)\).`,r`Giá trị cực đại là tung độ của điểm đó, khác với hoành độ cực đại.`,r`Vậy giá trị cực đại bằng 3.`]);
mc(53,'mono',r`Cho bảng biến thiên như hình. Mệnh đề nào đúng?`,[r`Đồng biến trên \((-\infty;-1/2)\) và \((3;+\infty)\).`,r`Đồng biến trên \((-1/2;+\infty)\).`,r`Nghịch biến trên \((3;+\infty)\).`,r`Đồng biến trên \((-\infty;3)\).`],2,[r`Hàm bị gián đoạn tại \(x=-1/2\); không thể gộp qua mốc này để kết luận đơn điệu.`,r`Trên \((3;+\infty)\), hàng đạo hàm mang dấu âm.`,r`Hàm nghịch biến trên \((3;+\infty)\), chọn C.`]);
mc(54,'mono',r`Hàm số liên tục trên \(\mathbb R\), có bảng xét dấu đạo hàm như hình. Số điểm cực trị bằng:`,['3','4','5','2'],0,[r`Đạo hàm đổi dấu tại −5, −1 và 4.`,r`Tại 3 và 5, đạo hàm bằng 0 nhưng không đổi dấu, nên không tạo cực trị.`,r`Hàm liên tục tại các mốc đổi dấu, nên có đúng 3 điểm cực trị.`]);
mc(55,'mono',r`Đồ thị của đạo hàm \(y=f'(x)\) như hình. Hàm số \(f\) có bao nhiêu điểm cực trị?`,['3','2','1','4'],3,[r`Cần đếm số lần đạo hàm đổi dấu, không phải đếm cực trị của đồ thị đạo hàm.`,r`Đường \(f'(x)\) cắt xuyên trục hoành tại −4, 0, 1 và 2, đổi dấu ở cả bốn mốc.`,r`Vì vậy hàm \(f\) có 4 điểm cực trị.`]);
mc(56,'mono',r`Cho \(f(x)=ax^4+bx^3+cx^2\) có đồ thị đạo hàm như hình. Số nghiệm thực phân biệt của \(4f(x)+5=0\) có xác định được từ dữ kiện này không?`,['4 nghiệm','Không đủ dữ kiện để xác định','3 nghiệm','1 nghiệm'],1,[r`Hình chỉ cho biết đạo hàm có ba nghiệm, với dấu \(-,+,-,+\). Do \(f(0)=0\), đồ thị hàm có dạng W và cực đại giữa bằng 0.`,r`Phương trình tương đương \(f(x)=-5/4\). Số giao điểm phụ thuộc độ cao hai cực tiểu, nhưng hình không ghi tọa độ hay giá trị để xác định chúng.`,r`Ví dụ \(f(x)=k(x^4-2x^2)\), \(k>0\), luôn có cùng kiểu đồ thị đạo hàm. Với \(k=1\), giá trị nhỏ nhất −1 nên vô nghiệm; với \(k=2\), hai cực tiểu −2 nên có 4 nghiệm. Kết luận 2 nghiệm trong lời giải PDF không suy ra được từ dữ kiện đã cho.`],{sourceCorrection:'Đổi lựa chọn B thành kết luận không đủ dữ kiện; đồ thị nguồn không cho độ cao cực tiểu.'});
mc(57,'asym',r`Có bao nhiêu số nguyên \(m\in[-10;10]\) để đồ thị \(y=\frac{x-2}{\sqrt{x^2+4m}}\) có đúng 4 đường tiệm cận?`,['11','10','8','9'],3,[r`Tại hai đầu vô cực: \[\lim_{x\to+\infty}y=1,\qquad\lim_{x\to-\infty}y=-1.\] Luôn có hai tiệm cận ngang khác nhau.`,r`Để có thêm hai tiệm cận đứng, cần \(x^2+4m=0\) có hai nghiệm, tức \(m<0\).`,r`Nếu \(m=-1\), tại nghiệm 2 cả tử và mẫu cùng về 0 nhưng \((x-2)/\sqrt{x^2-4}\to0\) khi \(x\to2^+\). Vì vậy chỉ còn tiệm cận đứng −2; phải loại \(m=-1\).`,r`Khi \(m<0,m\ne-1\), cả hai nghiệm mẫu đều có tử khác 0. Nhận \(m=-10,-9,\ldots,-2\): có 9 giá trị.`]);

function tf(n,type,prompt,statements,truth,steps,extra={}){
 add(n,type,prompt,undefined,truth.map(v=>v?'Đúng':'Sai'),steps,{kind:'true-false',statements,answerText:truth.map((v,i)=>'abcd'[i]+') '+(v?'Đúng':'Sai')).join('; '),...extra});
}
tf(58,'ext',r`Cho \(f(x)=2\cos x+x\). Xét tính đúng sai của các mệnh đề:`,[r`\(f(0)=2\), \(f(\pi/2)=\pi/2\).`,r`\(f'(x)=2\sin x+1\).`,r`Nghiệm của \(f'(x)=0\) trên \([0;\pi/2]\) là \(\pi/6\).`,r`Giá trị lớn nhất trên \([0;\pi/2]\) bằng \(\sqrt3+\pi/6\).`],[1,0,1,1],[r`a) \(f(0)=2\cdot1+0=2\); \(f(\pi/2)=2\cdot0+\pi/2=\pi/2\). Mệnh đề đúng.`,r`b) \(f'(x)=-2\sin x+1\), nên dấu trước sin trong mệnh đề sai.`,r`c) \(f'=0\iff\sin x=1/2\iff x=\pi/6+2k\pi\) hoặc \(x=5\pi/6+2k\pi\). Lọc trên đoạn chỉ còn \(x=\pi/6\). Mệnh đề đúng.`,r`d) So sánh \(f(0)=2\), \(f(\pi/2)=\pi/2\), \(f(\pi/6)=\sqrt3+\pi/6\approx2.256\). Giá trị cuối lớn nhất; mệnh đề đúng.`]);
tf(59,'ext',r`Cho \(f(x)=x^3-3x+91\).`,[r`\(f'(x)=3x^2-3\).`,r`Phương trình \(f'(x)=0\) có tập nghiệm \(\{1\}\).`,r`\(f(1)=89\).`,r`Giá trị nhỏ nhất trên \([-2;2]\) bằng 89.`],[1,0,1,1],[r`a) Đạo hàm từng hạng: \(f'(x)=3x^2-3\), đúng.`,r`b) \(3x^2-3=0\iff x^2=1\iff x=\pm1\). Tập nghiệm phải có cả −1 và 1, nên sai.`,r`c) \(f(1)=1-3+91=89\), đúng.`,r`d) Tính \(f(-2)=89\), \(f(-1)=93\), \(f(1)=89\), \(f(2)=93\). Giá trị nhỏ nhất bằng 89, đúng.`]);
tf(60,'mono',r`Cho \(f(x)=x-4\ln x\).`,[r`Tập xác định là \((0;+\infty)\).`,r`\(f'(x)=1-1/x\) với \(x>0\).`,r`Hàm đồng biến trên \((1;2)\).`,r`Giá trị cực tiểu bằng \(4-4\ln4\).`],[1,0,0,1],[r`a) Logarit cần \(x>0\), nên tập xác định đúng là \((0;+\infty)\).`,r`b) \(f'(x)=1-4/x=(x-4)/x\), không phải \(1-1/x\).`,r`c) Trên \((1;2)\), tử \(x-4<0\), mẫu \(x>0\), nên đạo hàm âm. Hàm nghịch biến, mệnh đề sai.`,r`d) Đạo hàm đổi dấu từ âm sang dương tại \(x=4\). Giá trị cực tiểu \(f(4)=4-4\ln4\), đúng.`]);
tf(61,'opt',r`Trên mỗi sào đất, nếu trồng \(n\) cây táo thì sản lượng trung bình một cây là \(f(n)=-0.06n^2-0.4n+320\) kg. Chi phí giống và chăm sóc là 560 nghìn đồng/cây; giá bán 50 nghìn đồng/kg và bán hết. Xét các mệnh đề về mật độ trồng nguyên dương:`,[r`Số cây tối đa có thể trồng mỗi sào là 70.`,r`Tổng sản lượng là \(S(n)=nf(n)\) kg.`,r`Doanh thu là \(D(n)=50(320n-0.4n^2-0.06n^3)\) nghìn đồng.`,r`Trồng 40 cây mỗi sào cho lợi nhuận lớn nhất.`],[0,1,1,0],[r`a) Điều kiện sản lượng không âm: \(-0.06n^2-0.4n+320\ge0\). Nghiệm dương của phương trình biên xấp xỉ 69,77; số nguyên lớn nhất là 69, không phải 70.`,r`b) Có \(n\) cây, mỗi cây cho \(f(n)\) kg, nên \(S(n)=nf(n)\), đúng.`,r`c) Nhân tổng sản lượng với giá bán: \(D(n)=50nf(n)=50(320n-0.4n^2-0.06n^3)\), đúng.`,r`d) Lợi nhuận \(P(n)=D(n)-560n=-3n^3-20n^2+15440n\). Đạo hàm \(P'(n)=-9n^2-40n+15440\) đổi từ dương sang âm tại \(n\approx39.26\). Với số cây nguyên, so sánh \(P(39)=393783\), \(P(40)=393600\) nghìn đồng: nên trồng 39 cây, mệnh đề sai.`]);
tf(62,'asym',r`Cho đồ thị \((C):y=\frac{-x^2+2x-5}{x-1}\).`,[r`Hàm đồng biến trên \((3;+\infty)\).`,r`Khoảng cách giữa hai điểm cực trị bằng \(2\sqrt5\).`,r`Tiệm cận xiên là \(y=-x+1\).`,r`Giá trị lớn nhất trên \([2;2026]\) bằng −4.`],[0,0,1,1],[r`a) Điều kiện \(x\ne1\). \[y'=\frac{(-2x+2)(x-1)-(-x^2+2x-5)}{(x-1)^2}=\frac{-(x-3)(x+1)}{(x-1)^2}.\] Khi \(x>3\), đạo hàm âm nên mệnh đề sai.`,r`b) Hai điểm cực trị \(M(-1;4)\), \(N(3;-4)\). \(MN=\sqrt{4^2+(-8)^2}=\sqrt{80}=4\sqrt5\), nên sai.`,r`c) Chia đa thức được \(y=-x+1-4/(x-1)\). Phần dư tiến về 0 ở vô cực, nên tiệm cận xiên đúng là \(y=-x+1\).`,r`d) Trên đoạn, hàm tăng từ 2 đến 3 rồi giảm sau 3. Vì vậy max tại 3, bằng \(f(3)=-4\), đúng.`]);
tf(63,'opt',r`Một hãng bán tai nghe giá 1,2 triệu đồng/chiếc, chi phí sản xuất 0,5 triệu đồng/chiếc. Chi quảng cáo \(x\ge0\) triệu đồng thì bán được \(n(x)=A+40\ln(1+x)\) chiếc. Khi chi \(e^2-1\) triệu đồng, bán được 190 chiếc.`,[r`\(A=110\).`,r`Lợi nhuận là \(L(x)=77+28\ln(1+x)-x\) triệu đồng.`,r`Chi quảng cáo 10 triệu đồng thì lợi nhuận làm tròn đến hàng đơn vị bằng 150 triệu đồng.`,r`Chi quảng cáo tối ưu là 26,799 triệu đồng, làm tròn đến hàng phần nghìn.`],[1,1,0,0],[r`a) \(A+40\ln(e^2)=190\Rightarrow A+80=190\Rightarrow A=110\), đúng.`,r`b) Lãi trước quảng cáo mỗi sản phẩm là \(1.2-0.5=0.7\) triệu. \(L(x)=0.7n(x)-x=77+28\ln(1+x)-x\), đúng.`,r`c) \(L(10)=67+28\ln11\approx134.14\) triệu, làm tròn 134 chứ không phải 150.`,r`d) \(L'(x)=28/(1+x)-1=(27-x)/(1+x)\). Đạo hàm đổi từ dương sang âm tại 27 nên chi phí tối ưu là 27 triệu đồng, mệnh đề sai.`]);
tf(64,'mono',r`Cho \(f(x)=x+\cos x-\sqrt3\sin x\).`,[r`\(f'(x)=1-\sin x+\sqrt3\cos x\).`,r`Hàm nghịch biến trên \((0;\pi/2)\).`,r`Hàm có đúng hai điểm cực trị trên \((0;2\pi)\).`,r`Giá trị lớn nhất trên \([0;\pi]\) bằng 1.`],[0,1,1,0],[r`a) \(f'(x)=1-\sin x-\sqrt3\cos x=1-2\sin(x+\pi/3)\). Mệnh đề sai dấu.`,r`b) Nếu \(0<x<\pi/2\), thì \(\pi/3<x+\pi/3<5\pi/6\), nên \(\sin(x+\pi/3)>1/2\). Đạo hàm âm, mệnh đề đúng.`,r`c) \(f'=0\iff x=-\pi/6+2k\pi\) hoặc \(x=\pi/2+2k\pi\). Trong khoảng được \(\pi/2,11\pi/6\); đạo hàm đổi dấu tại cả hai, nên đúng.`,r`d) Trong đoạn có điểm dừng \(\pi/2\), là điểm cực tiểu. So sánh hai đầu: \(f(0)=1\), \(f(\pi)=\pi-1>1\). Max bằng \(\pi-1\), mệnh đề sai.`]);
tf(65,'opt',r`Nồng độ thuốc được mô tả bởi \(f(t)=Ate^{kt}\) mg/ml với \(t\ge0\) tính bằng giờ. Biết \(f(1)=0.3\) mg/ml và tốc độ tăng lúc ban đầu là \(f'(0)=0.5\) mg/ml mỗi giờ.`,[r`\(f'(t)=Ae^{kt}(1+kt)\).`,r`\(A=2\).`,r`\(k=\ln(3/5)\).`,r`Nồng độ lớn nhất làm tròn đến hàng phần trăm bằng 0,38 mg/ml.`],[1,0,1,0],[r`a) Đạo hàm tích: \(f'=Ae^{kt}+Atke^{kt}=Ae^{kt}(1+kt)\), đúng.`,r`b) \(f'(0)=A=0.5\), nên \(A=2\) là sai.`,r`c) \(0.5e^k=0.3\Rightarrow e^k=3/5\Rightarrow k=\ln(3/5)<0\), đúng.`,r`d) Vì \(Ae^{kt}>0\), đạo hàm đổi từ dương sang âm tại \(t=-1/k\). \[f_{\max}=\frac{-0.5}{e\ln(3/5)}\approx0.3601.\] Làm tròn 0,36 mg/ml; mệnh đề sai.`]);
tf(66,'opt',r`Nhà máy bán mô tô giá 60 triệu đồng/chiếc. Chi phí mỗi ngày là \(C(x)=0.01x^3-1.5x^2+86x+1200\) triệu đồng, với số xe nguyên \(0\le x\le150\). Sản xuất bao nhiêu bán hết bấy nhiêu.`,[r`Lợi nhuận là \(L(x)=-0.01x^3+1.5x^2+26x-1200\).`,r`Lợi nhuận lớn nhất mỗi ngày bằng 1320 triệu đồng.`,r`Cần sản xuất ít nhất 50 chiếc để không lỗ.`,r`Nếu sản xuất 150 chiếc, giá bán tối thiểu để không lỗ là 94 triệu đồng/chiếc.`],[0,1,1,1],[r`a) \(L(x)=60x-C(x)=-0.01x^3+1.5x^2-26x-1200\). Hệ số của \(x\) là −26 nên sai.`,r`b) \(L'=-0.03x^2+3x-26\), hai nghiệm xấp xỉ 9,59 và 90,41. Max thực gần 90,41; so sánh \(L(90)=1320\), \(L(91)=1319.79\) và hai đầu đoạn đều nhỏ hơn. Max nguyên 1320, đúng.`,r`c) \[L(x)=-0.01(x+20)(x-50)(x-120).\] Trên miền cho phép, \(L(x)\ge0\iff50\le x\le120\). Số xe ít nhất 50, đúng.`,r`d) \(C(150)=14100\) triệu. Nếu giá là \(p\), không lỗ khi \(150p\ge14100\iff p\ge94\), đúng.`]);
tf(67,'opt',r`Độ cứng \(S\) tỉ lệ thuận với chiều rộng \(w\) và bình phương chiều dài \(d\). Thanh rộng 3 cm, dài 6 cm có độ cứng 108. Cắt thanh chữ nhật từ khúc gỗ tròn đường kính 24 cm như hình. Trong các công thức dưới đây, \(w,d\) cùng tính bằng cm.`,[r`\(d^2+w^2=576\).`,r`\(S=2dw^2\).`,r`\(S(w)=576w-w^3\), \(0<w<24\).`,r`Độ cứng lớn nhất làm tròn đến hàng đơn vị là 5321.`],[1,0,1,1],[r`a) Đường chéo hình chữ nhật bằng đường kính 24. Theo Pythagore, \(d^2+w^2=24^2=576\), đúng.`,r`b) \(S=kwd^2\). Từ \(108=k\cdot3\cdot6^2\) được \(k=1\), nên \(S=wd^2\), mệnh đề sai.`,r`c) Thay \(d^2=576-w^2\): \(S=w(576-w^2)=576w-w^3\), đúng.`,r`d) \(S'=576-3w^2=0\Rightarrow w=8\sqrt3\) trong miền. Đạo hàm đổi từ dương sang âm, nên \(S_{\max}=3072\sqrt3\approx5320.86\), làm tròn 5321. Mệnh đề đúng; nhãn “Sai” của lời giải PDF bị nhầm.`],{sourceCorrection:'Chuẩn hóa w,d sang cm; sửa nhãn ý d thành Đúng vì 3072√3 làm tròn là 5321.'});
tf(68,'opt',r`Trong 18 tuần từ khi trồng cà chua, chiều cao cây là \(h(t)=50\log_3(2t+1)+10\) cm, \(0\le t\le18\). Từ tuần thứ 8 cây kết trái; đường kính trái là \(d(t)=3^{(2t-15)/(t-7)}-3\) cm, \(8\le t\le18\).`,[r`Tốc độ tăng chiều cao ở tuần 7 làm tròn đến hàng phần trăm là 6,07 cm/tuần.`,r`Cây 4 tuần tuổi cao 110 cm.`,r`Sau 4 tuần kể từ khi kết trái, đường kính trái lớn hơn 9,98 cm.`,r`Chiều cao cây liên tục tăng trong suốt 18 tuần.`],[1,1,0,1],[r`a) \(h'(t)=100/[(2t+1)\ln3]\). Thay 7: \(h'(7)=100/(15\ln3)\approx6.07\), đúng.`,r`b) \(h(4)=50\log_3 9+10=100+10=110\), đúng.`,r`c) Sau khi kết trái 4 tuần là \(t=8+4=12\), không phải 4. \(d(12)=3^{9/5}-3\approx4.22<9.98\), sai.`,r`d) \(h'(t)>0\) với \(0\le t\le18\), nên chiều cao tăng, đúng.`]);
tf(69,'mono',r`Cho \(y=\frac{x^2+3x+6}{x+1}\).`,[r`\(y'=\frac{x^2+2x-3}{(x+1)^2}\), \(x\ne-1\).`,r`Điểm cực tiểu của đồ thị là \((1;5)\).`,r`Hàm nghịch biến trên \((-3;1)\).`,r`Tổng khoảng cách từ hai điểm cực trị đến trục hoành bằng 2.`],[1,1,0,0],[r`a) Điều kiện \(x\ne-1\). Đạo hàm thương: \[y'=\frac{(2x+3)(x+1)-(x^2+3x+6)}{(x+1)^2}=\frac{(x+3)(x-1)}{(x+1)^2}.\] Mệnh đề đúng.`,r`b) Đạo hàm đổi âm sang dương tại 1, \(f(1)=10/2=5\), nên \((1;5)\) là cực tiểu, đúng.`,r`c) Khoảng \((-3;1)\) chứa −1 không thuộc tập xác định. Phải tách thành \((-3;-1)\), \((-1;1)\), nên sai.`,r`d) Hai điểm cực trị \((-3;-3)\), \((1;5)\). Tổng khoảng cách đến trục hoành là \(|-3|+|5|=8\), không phải 2.`]);
tf(70,'tangent',r`Cho \(f(x)=x^3+ax^2+bx+c\) có đồ thị như hình.`,[r`Hàm số có hai điểm cực trị là 0 và 2.`,r`\(b=0\).`,r`\(c=-2\).`,r`\(f(x)=x^3-6x^2+2\).`],[1,1,0,0],[r`a) Đồ thị đổi chiều tại hoành độ 0 và 2, nên đúng.`,r`b) \(f'=3x^2+2ax+b\). Từ \(f'(0)=0\) được \(b=0\); từ \(f'(2)=0\) được \(12+4a=0\Rightarrow a=-3\).`,r`c) Đồ thị qua \((0;2)\), nên \(c=f(0)=2\), mệnh đề sai.`,r`d) Các hệ số cho \(f(x)=x^3-3x^2+2\), không phải hệ số −6; mệnh đề sai.`]);
tf(71,'opt',r`Trong 15 phút đầu một cơn mưa, lưu lượng sông là \(L(t)=at^3+bt^2+ct+d\) m³/phút. Biết \(L(0)=200\), sau 10 phút đạt lưu lượng lớn nhất 400. Cảnh báo khi lưu lượng từ 300 trở lên và bắt đầu ở phút thứ 4.`,[r`\(d=200\).`,r`\(L'(10)=300a+20b+c=0\).`,r`\(b>2\).`,r`Khoảng thời gian cảnh báo làm tròn đến hàng phần mười là 10,8 phút.`],[1,1,0,0],[r`a) Thay 0: \(L(0)=d=200\), đúng.`,r`b) Vì 10 là điểm max trong đoạn nên \(L'(10)=0\). Với \(L'=3at^2+2bt+c\), ta được đúng phương trình đã nêu.`,r`c) Dùng \(L(10)=400\), \(L(4)=300\), \(L'(10)=0\): \[100a+10b+c=20,\quad16a+4b+c=25,\quad300a+20b+c=0.\] Giải được \(a=-7/36,b=17/9,c=185/9\). Vì \(17/9<2\), mệnh đề sai.`,r`d) \[L(t)-300=-\frac1{36}(t-4)(7t^2-40t-900).\] Hai mốc trong đoạn là 4 và \((20+10\sqrt{67})/7\approx14.55\). Cảnh báo trong khoảng dài khoảng \(14.55-4=10.55\), làm tròn 10,6 phút, không phải 10,8.`]);
tf(72,'opt',r`Dùng 8 m dây thép uốn một cửa sổ gồm khung chữ nhật rộng \(x\), cao \(y\) và nửa hình tròn gắn phía trên như hình. Dây tạo cả các đường viền và thanh ngang giữa hai phần.`,[r`Chiều dài dây tạo cung bán nguyệt là \(\pi x/2\).`,r`\(y=4-x(4+\pi)/4\).`,r`Diện tích cửa sổ là \(S=4x-x^2\).`,r`Khi diện tích lớn nhất, \(y=16/(8+\pi)\).`],[1,1,0,1],[r`a) Bán kính nửa tròn bằng \(x/2\), cung dài \(\pi x/2\), đúng.`,r`b) Tổng dây: \(2x+2y+\pi x/2=8\). Suy ra \(y=4-x-\pi x/4\), đúng. Điều kiện thực tế \(x>0,y>0\).`,r`c) \[S=xy+\frac{\pi x^2}8=4x-\left(1+\frac\pi8\right)x^2.\] Mệnh đề thiếu diện tích tròn và ảnh hưởng dây, nên sai.`,r`d) \(S'=4-(2+\pi/4)x=0\Rightarrow x=16/(8+\pi)\). Vì \(S''<0\), đây là max; thay lại được \(y=16/(8+\pi)\), đúng.`]);
tf(73,'tangent',r`Cho \(f(x)=\sin2x\).`,[r`Tập giá trị là \([-1;1]\).`,r`\(f'(x)=\cos2x\).`,r`Hệ số góc tiếp tuyến tại \(x_0=\pi\) bằng 1.`,r`Tiếp tuyến tại \(x_0=\pi\) có phương trình \(y=2x-2\pi\).`],[1,0,0,1],[r`a) \(2x\) nhận mọi giá trị thực nên sin nhận toàn bộ \([-1;1]\), đúng.`,r`b) Đạo hàm hàm hợp: \(f'=2\cos2x\), mệnh đề thiếu hệ số 2.`,r`c) \(f'(\pi)=2\cos2\pi=2\), không phải 1.`,r`d) \(f(\pi)=0\), nên tiếp tuyến \(y=f'(\pi)(x-\pi)+f(\pi)=2(x-\pi)\), đúng.`]);
tf(74,'mono',r`Hàm \(f\) liên tục trên \(\mathbb R\), có đồ thị đạo hàm là parabol đi qua \(O\) và \(A(1;0)\) như hình.`,[r`\(f'(x)=0\) khi \(x=0\) hoặc \(x=1\).`,r`Hàm nghịch biến trên \((0;1)\).`,r`Hàm có 2 điểm cực trị.`,r`\(f(1/2)>f(1)\).`],[1,1,1,1],[r`a) Hai giao điểm với trục hoành có hoành độ 0 và 1, đúng.`,r`b) Giữa hai nghiệm, parabol đạo hàm nằm dưới trục hoành, nên \(f'<0\), đúng.`,r`c) Parabol cắt xuyên trục tại cả hai nghiệm; đạo hàm đổi dấu ở 0 và 1, nên có 2 cực trị, đúng.`,r`d) Hàm giảm trên \((0;1)\) và liên tục tại 1, nên từ \(1/2<1\) suy ra \(f(1/2)>f(1)\), đúng.`]);
tf(75,'mono',r`Cho \(f(x)=\log_{1/2}(x^2-5x+4)\).`,[r`Tập xác định là \((-\infty;1]\cup[4;+\infty)\).`,r`\(f'(x)=\frac{5-2x}{(x^2-5x+4)\ln2}\).`,r`Hàm đồng biến trên \((-\infty;5/2)\).`,r`Bất phương trình \(f(x)>0\) có đúng 4 nghiệm nguyên.`],[0,1,0,0],[r`a) Điều kiện \((x-1)(x-4)>0\iff x<1\) hoặc \(x>4\). Không lấy đầu mút, nên sai.`,r`b) \[f'=\frac{2x-5}{(x^2-5x+4)\ln(1/2)}=\frac{5-2x}{(x^2-5x+4)\ln2}.\] Mệnh đề đúng.`,r`c) Hàm không xác định trên \([1;4]\), nên không thể đồng biến trên khoảng đã nêu. Hàm chỉ đồng biến trên \((-\infty;1)\).`,r`d) Vì cơ số nhỏ hơn 1: \(f(x)>0\iff0<x^2-5x+4<1\). Kết hợp điều kiện cho \(((5-\sqrt{13})/2;1)\cup(4;(5+\sqrt{13})/2)\). Không có số nguyên trong hai khoảng, nên sai.`]);
tf(76,'ext',r`Cho \(f(x)=\sin x-\sqrt3\cos x-2\).`,[r`\(f(\pi/2)=-1\).`,r`\(f'(x)=\cos x-\sqrt3\sin x\).`,r`Nghiệm của \(f'(x)=0\) trên \([0;\pi]\) là \(5\pi/6\).`,r`Giá trị lớn nhất trên \([0;\pi]\) bằng \(\sqrt3-2\).`],[1,0,1,0],[r`a) \(f(\pi/2)=1-0-2=-1\), đúng.`,r`b) \(f'=cos x+\sqrt3\sin x=2\sin(x+\pi/6)\), nên mệnh đề sai dấu.`,r`c) \(f'=0\iff x=-\pi/6+k\pi\). Chỉ \(k=1\) cho nghiệm trong đoạn, tức \(5\pi/6\), đúng.`,r`d) Đạo hàm dương trước \(5\pi/6\), âm sau đó. Max là \(f(5\pi/6)=1/2+3/2-2=0\), không phải \(\sqrt3-2\).`]);
tf(77,'opt',r`Đèn đặt trên cột cao 40 m. Một vật rơi tự do từ độ cao 40 m, cách đèn 10 m theo phương ngang, vận tốc ban đầu bằng 0; \(g=10\) m/s². Gọi \(h(t)\) là độ cao và \(L(t)\) là khoảng cách từ bóng đến chân đèn.`,[r`\(h(t)=40-5t^2\) mét.`,r`Tốc độ khi vật chạm đất làm tròn đến hàng phần mười bằng 28,2 m/s.`,r`\(L(t)=10h(t)/(40-h(t))\).`,r`Lúc vật chạm đất, bóng hướng về chân đèn với tốc độ làm tròn 7,1 m/s.`],[1,0,0,1],[r`a) Quãng rơi \(s=gt^2/2=5t^2\), nên \(h=40-5t^2\), đúng.`,r`b) \(h=0\Rightarrow t=2\sqrt2\). Tốc độ \(|h'|=10t=20\sqrt2\approx28.3\) m/s, nên sai.`,r`c) Hai tam giác đồng dạng cho \((40-h)/40=10/L\), nên \(L=400/(40-h)\), mệnh đề sai.`,r`d) Với \(t>0\), \(L=80/t^2\), \(L'=-160/t^3\). Tại \(2\sqrt2\), \(L'=-5\sqrt2\approx-7.1\). Dấu âm chỉ bóng tiến về chân đèn; mệnh đề đúng.`]);
tf(78,'ext',r`Chu kì đầu của sóng trên máy hiện sóng được mô hình bằng \(y=\frac12\sin(2\pi x)+\frac14\sin(4\pi x)\) cm, \(0\le x\le1\), với \(x\) tính bằng giây.`,[r`\(y(0)=y(1)=0\).`,r`\(y'=\cos(2\pi x)+\cos(4\pi x)\).`,r`Trong giây đầu tiên, tốc độ bằng 0 tại 2 thời điểm.`,r`Độ cao lớn nhất trong giây đầu làm tròn đến hàng phần mười là 6,5 mm.`],[1,0,0,1],[r`a) Ở 0 và 1, các góc là bội của \(2\pi\), nên hai sin bằng 0, đúng.`,r`b) Đạo hàm đúng là \(y'=\pi[\cos(2\pi x)+\cos(4\pi x)]\), mệnh đề thiếu \(\pi\).`,r`c) Đặt \(u=\cos2\pi x\). Đạo hàm bằng 0 khi \(u+2u^2-1=(2u-1)(u+1)=0\). Trong đoạn được \(x=1/6,1/2,5/6\), có 3 thời điểm, nên sai.`,r`d) So sánh các điểm dừng và hai đầu: max tại \(x=1/6\), \(y=3\sqrt3/8\approx0.64952\) cm = 6,4952 mm, làm tròn 6,5 mm. Mệnh đề đúng.`]);
tf(79,'tangent',r`Cho \((C):y=-x^3+3x^2+4\).`,[r`Tập xác định \(D=\mathbb R\) và \(y'=-3x^3+6x\).`,r`Hàm đồng biến trên \((0;2)\).`,r`Đường thẳng qua hai điểm cực trị là \(2x+y-4=0\).`,r`Diện tích tam giác \(OAB\) bằng 4, với \(A,B\) là hai điểm cực trị.`],[0,1,0,1],[r`a) Tập xác định đúng, nhưng đạo hàm là \(-3x^2+6x\), không phải lũy thừa 3, nên mệnh đề sai.`,r`b) \(y'=-3x(x-2)>0\) khi \(0<x<2\), nên đúng.`,r`c) Hai điểm cực trị \(A(0;4),B(2;8)\). Hệ số góc là \((8-4)/(2-0)=2\); đường thẳng \(y=2x+4\), tức \(2x-y+4=0\). Mệnh đề sai.`,r`d) \(S_{OAB}=|0\cdot8-2\cdot4|/2=4\), đúng.`]);
tf(80,'mono',r`Cho \(f(x)=e^{x^2}-x^2\).`,[r`Tập xác định là \((0;+\infty)\).`,r`\(f'(x)=2xe^{x^2}-2x\).`,r`Phương trình \(f'(x)=0\) có tập nghiệm \(\{-1;0;1\}\).`,r`Giá trị cực tiểu bằng 1.`],[0,1,0,1],[r`a) Mũ và đa thức xác định với mọi số thực, nên \(D=\mathbb R\), mệnh đề sai.`,r`b) Đạo hàm hàm hợp cho \(f'=2xe^{x^2}-2x\), đúng.`,r`c) \(f'=2x(e^{x^2}-1)=0\). Cả hai thừa số chỉ có thể triệt tiêu khi \(x=0\), nên tập nghiệm \(\{0\}\), sai.`,r`d) Với \(x\ne0\), \(e^{x^2}-1>0\). Dấu đạo hàm cùng dấu \(x\), nên cực tiểu tại 0, \(f(0)=1\), đúng.`]);
tf(81,'ext',r`Chiều dài bóng của người cao \(a\) mét được mô hình bằng \(S(t)=a\left|\cot\left(\frac{\pi t}{12}\right)\right|\) mét, trong đó \(t\) là số giờ tính từ 6 giờ sáng. Lúc 9 giờ sáng, bóng dài 1,8 m.`,[r`Không xác định được bóng theo mô hình vào 6 giờ sáng và 18 giờ tối.`,r`Từ 6 giờ đến 18 giờ, bóng luôn giảm chiều dài.`,r`Người cao hơn 1,75 m.`,r`Bóng dài 1 m tại \(t=4.07\) và \(t=7.94\), làm tròn đến hàng phần trăm.`],[1,0,1,0],[r`a) Hai thời điểm tương ứng \(t=0,12\); cotang không xác định khi góc bằng 0 hoặc \(\pi\), đúng.`,r`b) Trên \((0;6)\), bóng giảm về 0; trên \((6;12)\), bóng tăng trở lại. Vì có dấu giá trị tuyệt đối, mệnh đề luôn giảm là sai.`,r`c) Lúc 9 giờ, \(t=3\) và \(|\cot(\pi/4)|=1\), nên \(a=1.8>1.75\), đúng.`,r`d) \(S=1\iff|\cot(\pi t/12)|=5/9\). Nghiệm \(t_1=(12/\pi)\arctan(9/5)\approx4.06\), \(t_2=12-t_1\approx7.94\). Thời điểm đầu không phải 4,07, nên sai.`]);
tf(82,'opt',r`Sư tử đuổi ngựa vằn trên một đường thẳng, khoảng cách ban đầu 40 m. Tốc độ sư tử \(v_1(t)=15e^{-0.1t}\), ngựa vằn \(v_2(t)=20-20e^{-0.1t}\) m/s, \(0\le t\le60\).`,[r`Tốc độ ngựa vằn ban đầu là 20 m/s.`,r`Tốc độ sư tử giảm, tốc độ ngựa vằn tăng.`,r`Khoảng cách nhỏ nhất khi \(v'_1=v'_2\), bằng 1,72 m sau khi làm tròn.`,r`Sư tử không bắt được ngựa vằn; khoảng cách nhỏ nhất làm tròn 1,92 m.`],[0,1,0,1],[r`a) \(v_2(0)=20-20=0\), sai.`,r`b) \(v'_1=-1.5e^{-0.1t}<0\), \(v'_2=2e^{-0.1t}>0\), đúng.`,r`c) Khoảng cách có \(d'=v_2-v_1=20-35e^{-0.1t}\). Điều kiện gần nhất là tốc độ bằng nhau, không phải đạo hàm tốc độ bằng nhau. \(t_*=10\ln(7/4)\).`,r`d) Tích phân độ chênh tốc độ cho \(d(t)=40+20t-350(1-e^{-0.1t})\). Tại \(t_*\), \(d_{\min}=200\ln(7/4)-110\approx1.92>0\), nên không đuổi kịp; đúng.`]);
tf(83,'opt',r`Hai nguồn sáng giống nhau đặt tại \((0;0)\), \((10;0)\). Điểm \(P(x;d)\), \(d>0\), nằm trên đường thẳng song song với đường nối hai nguồn. Cường độ mỗi nguồn tại P tỉ lệ nghịch bình phương khoảng cách, hệ số \(k>0\).`,[r`Khoảng cách là \(r_1=\sqrt{x^2+d^2}\), \(r_2=\sqrt{(x+10)^2+d^2}\).`,r`Tổng cường độ \(I(x)=k\left(\frac1{x^2+d^2}+\frac1{(x-10)^2+d^2}\right)\).`,r`Khi \(d=5\), \(I\) đạt cực tiểu tại \(x=5\).`,r`Khi \(d=10\), \(I\) không đạt cực tiểu tại vị trí chính giữa.`],[0,1,1,1],[r`a) Hiệu hoành độ tới nguồn thứ hai là \(x-10\), nên khoảng cách đúng \(r_2=\sqrt{(x-10)^2+d^2}\); mệnh đề sai.`,r`b) Cộng hai cường độ \(k/r_1^2+k/r_2^2\) được đúng công thức đã nêu.`,r`c) Đối xứng cho \(I'(5)=0\). Tính \[I''(5)=\frac{4k(75-d^2)}{(25+d^2)^3}.\] Khi \(d=5\), biểu thức dương nên điểm giữa là cực tiểu địa phương, đúng.`,r`d) Khi \(d=10\), \(I''(5)<0\) nên điểm giữa là cực đại địa phương, không phải cực tiểu, đúng. Nếu xét toàn bộ đường thẳng vô hạn, cường độ tiến về 0 ở xa nhưng không đạt 0; không nhầm cực tiểu địa phương với giá trị nhỏ nhất toàn cục.`]);
tf(84,'ext',r`Vật được phóng lên từ độ cao 5 m, vận tốc đầu 39,2 m/s. Bỏ qua cản không khí, độ cao là \(h(t)=5+39.2t-4.9t^2\) mét, chọn chiều dương hướng lên.`,[r`Vận tốc sau 3 giây bằng 4,6 m/s.`,r`Độ cao lớn nhất bằng 84,3 m tại \(t=4\) giây.`,r`Khoảng thời gian vật cao hơn 10 m dài hơn 7 giây.`,r`Vận tốc lúc chạm đất xấp xỉ −40,43 m/s.`],[0,0,1,1],[r`a) \(v(t)=h'(t)=39.2-9.8t\); \(v(3)=9.8\), không phải 4,6, nên sai.`,r`b) \(v=0\Rightarrow t=4\). Parabol quay xuống nên max tại đó, nhưng \(h(4)=5+156.8-78.4=83.4\) m. Mệnh đề 84,3 m sai; lời giải PDF gắn nhãn nhầm.`,r`c) \(h>10\iff-4.9t^2+39.2t-5>0\). Khoảng nghiệm có độ dài \(2\sqrt{734}/7\approx7.74>7\) giây, đúng.`,r`d) Nghiệm dương của \(h=0\) là \(t=(28+\sqrt{834})/7\). Thay vào \(v=39.2-9.8t\) được \(-1.4\sqrt{834}\approx-40.43\), đúng.`],{sourceCorrection:'Sửa ý b thành Sai: độ cao tính được là 83,4 m, không phải 84,3 m.'});

function short(n,type,prompt,value,answerText,steps,extra={}){
 add(n,type,prompt,undefined,undefined,steps,{kind:'short',value,answerText,tolerance:0.000051,...extra});
}
short(85,'opt',r`Doanh nghiệp sản xuất \(x\in\mathbb N^*,1\le x\le4500\) sản phẩm/tháng. Doanh thu khi bán hết là \(F(x)=-0.01x^2+450x\) nghìn đồng; chi phí bình quân một sản phẩm \(G(x)=30000/x+340\) nghìn đồng. Cần sản xuất ít nhất bao nhiêu sản phẩm để lợi nhuận lớn hơn 100 triệu đồng?`,1347,'1347 sản phẩm',[r`Tổng chi phí là \(xG(x)=30000+340x\). Lợi nhuận \[L(x)=F(x)-xG(x)=-0.01x^2+110x-30000\] tính bằng nghìn đồng.`,r`Đổi 100 triệu thành 100000 nghìn: \[L(x)>100000\iff x^2-11000x+13000000<0.\]`,r`Hai nghiệm biên \(5500\pm500\sqrt{69}\). Suy ra \(5500-500\sqrt{69}<x<5500+500\sqrt{69}\), tức khoảng \((1346.69;9653.31)\).`,r`Kết hợp số nguyên \(1\le x\le4500\): số nhỏ nhất là 1347. Kiểm tra \(L(1346)=99942.84<100000\), \(L(1347)=100025.91>100000\).`],{unit:'sản phẩm',tolerance:0});
short(86,'opt',r`Tạo một khối pha lê hình chóp đều đáy vuông, tổng diện tích bốn mặt bên và đáy bằng 100 cm². Tìm thể tích lớn nhất (cm³), làm tròn đến hàng phần chục.`,58.9,r`\(\frac{125\sqrt2}3\approx58.9\) cm³`,[r`Gọi cạnh đáy \(a>0\), đường cao mặt bên \(b>0\). Diện tích \(a^2+2ab=100\Rightarrow b=(100-a^2)/(2a)\).`,r`Chiều cao khối chóp \[h=\sqrt{b^2-a^2/4}=\frac5a\sqrt{100-2a^2}.\] Điều kiện \(0<a<5\sqrt2\).`,r`Thể tích \[V(a)=\frac13a^2h=\frac53a\sqrt{100-2a^2},\quad V'(a)=\frac53\frac{100-4a^2}{\sqrt{100-2a^2}}.\]`,r`Đạo hàm bằng 0 tại \(a=5\), dương trước và âm sau. \(V_{\max}=\frac53\cdot5\sqrt{50}=125\sqrt2/3\approx58.9256\), làm tròn 58,9 cm³.`],{unit:'cm³',tolerance:0.000051});
short(87,'opt',r`Ca nô tuần tra ngược dòng 60 km rồi xuôi dòng 60 km về điểm đầu. Dòng nước chảy 5 km/h. Xăng tiêu thụ \(L=kv^2t\) lít, \(v\) là tốc độ so với mặt nước (km/h), \(t\) tính bằng giờ. Khi nước yên, tốc độ 20 km/h tiêu thụ 10 lít/giờ. Cài đặt tốc độ \(v\) không đổi bao nhiêu để ít tốn xăng nhất? Làm tròn đến hàng phần trăm.`,8.66,r`\(5\sqrt3\approx8.66\) km/h`,[r`Từ lần chạy thử: \(10=k\cdot20^2\cdot1\Rightarrow k=1/40\). Điều kiện đi ngược dòng là \(v>5\).`,r`Thời gian hai chiều \(t_1=60/(v-5)\), \(t_2=60/(v+5)\). Tổng xăng \[F(v)=\frac{v^2}{40}\left(\frac{60}{v-5}+\frac{60}{v+5}\right)=\frac{3v^3}{v^2-25}.\]`,r`\[F'(v)=\frac{9v^2(v^2-25)-6v^4}{(v^2-25)^2}=\frac{3v^2(v^2-75)}{(v^2-25)^2}.\]`,r`Trên \((5;+\infty)\), đạo hàm âm trước \(5\sqrt3\), dương sau đó. Tốc độ tối ưu \(v=5\sqrt3\approx8.66\) km/h.`],{unit:'km/h'});
short(88,'opt',r`Một que sào thẳng chạm kín các điểm của hành lang chữ L như hình, với hai bề rộng \(a=24\), \(b=3\). Nếu chiều dài tối thiểu của sào là \(l\), tính \(l^2\).`,1125,r`\(l^2=1125\)`,[r`Đặt \(DF=x>0\) như hình. Hai tam giác vuông đồng dạng cho \(EB/ED=AF/DF\), nên \(EB=ab/x\).`,r`Theo Pythagore: \[l^2=F(x)=(x+b)^2+\left(a+\frac{ab}x\right)^2.\]`,r`\[F'(x)=2(x+b)\left(1-\frac{a^2b}{x^3}\right).\] Đạo hàm bằng 0 khi \(x^3=a^2b=24^2\cdot3=1728\), nên \(x=12\).`,r`Đạo hàm âm trước 12, dương sau 12. \[l^2=15^2+(24+72/12)^2=225+900=1125.\]`],{tolerance:0});
short(89,'opt',r`Giàn khoan của Nam cách bờ thẳng 10 km, chân đường vuông góc xuống bờ là O. Cơ quan Mai ở M trên bờ, \(OM=6\) km. Nam đi thuyền 15 km/h, Mai đi bộ 5 km/h; cả hai cùng xuất phát và đến điểm P trên đoạn OM cùng lúc như hình. P cách cơ quan Mai bao nhiêu km? Làm tròn đến hàng phần trăm.`,3.44,r`\(MP=\frac{-3+\sqrt{281}}4\approx3.44\) km`,[r`Đặt \(MP=x\), \(0\le x\le6\), thì \(OP=6-x\). Quãng thuyền đi \(NP=\sqrt{100+(6-x)^2}\).`,r`Bằng thời gian: \[\frac{\sqrt{100+(6-x)^2}}{15}=\frac x5\iff\sqrt{100+(6-x)^2}=3x.\]`,r`Vì \(x\ge0\), bình phương tương đương: \(100+36-12x+x^2=9x^2\iff2x^2+3x-34=0\).`,r`Hai nghiệm \((-3\pm\sqrt{281})/4\). Loại nghiệm âm; nghiệm dương thuộc \([0;6]\), cho \(MP\approx3.44\) km.`],{unit:'km'});
short(90,'opt',r`Viên gạch vuông cạnh 60 cm có họa tiết chữ nhật trắng cùng tâm. Các đỉnh chữ nhật nằm trên hai parabol đối xứng qua tâm; mỗi parabol có đỉnh tại trung điểm một cạnh và đi qua hai đầu mút cạnh đối diện như hình. Men trắng giá 80 nghìn đồng/m², men màu giá 200 nghìn đồng/m². Tìm chi phí nguyên liệu thấp nhất cho một viên, làm tròn đến hàng phần mười (nghìn đồng).`,60.2,r`\(72-4.8\sqrt6\approx60.2\) nghìn đồng`,[r`Đổi cạnh gạch thành 0,6 m; chọn tâm làm gốc. Parabol phía trên có đỉnh \((0;0.3)\), qua \((0.3;-0.3)\), nên \[y=-\frac{20}3x^2+0.3.\]`,r`Với nửa chiều rộng chữ nhật \(x\), \(0<x<\sqrt{0.045}\), diện tích trắng \[S(x)=4xy=-\frac{80}3x^3+1.2x.\]`,r`Chi phí \(T=80S+200(0.36-S)=72-120S\). Muốn min chi phí thì max diện tích trắng. \(S'=-80x^2+1.2=0\Rightarrow x=\sqrt6/20\).`,r`Đạo hàm đổi từ dương sang âm; \(S_{\max}=\sqrt6/25\). \(T_{\min}=72-120\sqrt6/25=72-4.8\sqrt6\approx60.2424\), làm tròn 60,2 nghìn đồng.`],{unit:'nghìn đồng'});
short(91,'opt',r`Cấp số cộng \((a_n)\) có \(a_1,d\) nguyên dương và thỏa \(2^{a_8}=2^{27}a_8\). Tìm giá trị nhỏ nhất của \(a_3\).`,12,'12',[r`Đặt \(x=a_8\in\mathbb N^*\). Điều kiện là \(2^x/x=2^{27}\). Với \(x\ge2\), tỉ số hai số liên tiếp của \(2^x/x\) bằng \(2x/(x+1)>1\).`,r`Giá trị tại 1 và 2 đều bằng 2; tại 32: \(2^{32}/32=2^{27}\). Tính tăng trên các số nguyên từ 2 trở đi cho nghiệm duy nhất \(a_8=32\).`,r`\(a_1+7d=32\), với \(a_1,d\ge1\), nên \(d\le4\). Suy ra \(a_3=a_1+2d=32-5d\).`,r`Để min, lấy \(d=4\). Khi đó \(a_1=4>0\), \(a_3=32-20=12\).`],{tolerance:0});
short(92,'opt',r`Một công ty mô hình lợi nhuận theo lượng tồn kho nguyên \(x\), \(1\le x\le1200\), bởi \(L(x)=1500+400\ln(x/1200)-x\) triệu đồng. Lợi nhuận tối đa bằng bao nhiêu triệu đồng, làm tròn đến hàng đơn vị?`,661,r`\(1100-400\ln3\approx661\) triệu đồng`,[r`Điều kiện logarit là \(x>0\), đã thỏa trên đoạn.`,r`\[L'(x)=400\cdot\frac{1/1200}{x/1200}-1=\frac{400}x-1=\frac{400-x}x.\]`,r`Đạo hàm dương khi \(x<400\), âm khi \(x>400\). Giá trị tối ưu tại \(x=400\), là số nguyên được phép.`,r`\(L(400)=1500+400\ln(1/3)-400=1100-400\ln3\approx660.555\). Làm tròn được 661 triệu đồng.`],{unit:'triệu đồng',tolerance:0});
short(93,'tangent',r`Trên hệ trục Oxy, mỗi đơn vị dài 10 m, con dốc là đồ thị \(y=\sqrt x\). Tiếp tuyến tại P cắt Ox tại A; đoạn AP dài 80 m như hình. P cao hơn mặt đất bao nhiêu mét? Làm tròn đến hàng phần mười.`,19.7,r`\(10\sqrt{\frac{-1+5\sqrt{41}}8}\approx19.7\) m`,[r`Gọi \(P(x_0;\sqrt{x_0})\), \(x_0>0\). Tiếp tuyến \[y=\frac{x-x_0}{2\sqrt{x_0}}+\sqrt{x_0}.\]`,r`Cho \(y=0\) được \(x=-x_0\), nên \(A(-x_0;0)\). Vì 1 đơn vị bằng 10 m, \(AP=8\) đơn vị.`,r`\[AP^2=(2x_0)^2+(\sqrt{x_0})^2=64\iff4x_0^2+x_0-64=0.\] Nghiệm dương \(x_0=(-1+5\sqrt{41})/8\).`,r`Chiều cao thực là \(10\sqrt{x_0}\approx19.69\) m, làm tròn 19,7 m.`],{unit:'m'});
short(94,'opt',r`Thanh sắt AB dài 21 cm. Chọn ngẫu nhiên, đồng khả năng, hai mốc M,N trong 20 vị trí cách A lần lượt 1,2,…,20 cm, rồi gập thanh tại hai mốc. Viết \(x=AM,y=MN,z=NB\). Xác suất để A có thể chạm B là \(a/b\) tối giản. Tính \(a+b\).`,49,'49',[r`Số cách chọn hai mốc là \(\binom{20}2=190\). Mỗi cách tương ứng bộ nguyên dương \(x+y+z=21\).`,r`Gập khép được khi ba đoạn tạo tam giác: mỗi cạnh nhỏ hơn 10,5, tức \(x,y,z\le10\). Tam giác suy biến không xảy ra vì chu vi 21 lẻ.`,r`Đặt \(u=11-x,v=11-y,w=11-z\). Khi đó các số nguyên dương có tổng 12; số bộ là \(\binom{11}2=55\). Mỗi số tự động không quá 10 nên phép đổi tương ứng hai chiều.`,r`Xác suất \(55/190=11/38\). Vậy \(a+b=11+38=49\).`],{tolerance:0});
short(95,'opt',r`Hộp diêm dài 6 cm, thể tích 24 cm³; rộng x, cao y. Khay bên trong gấp từ tấm bìa chữ nhật như hình 2, bốn hình vuông cạnh y ở góc bị cắt bỏ. Vỏ ngoài từ tấm bìa như hình 3; vật liệu hai mặt đánh lửa đắt gấp ba vật liệu còn lại trên cùng đơn vị diện tích. Tìm x để tổng chi phí nhỏ nhất, làm tròn đến hàng phần trăm (cm).`,3.56,r`\(x\approx3.56\) cm`,[r`Thể tích \(6xy=24\Rightarrow x=4/y\), \(y>0\). Gọi đơn giá thường là T; mặt đánh lửa đơn giá 3T.`,r`Tính cả vật liệu khay bị cắt bỏ: \[F/T=(x+2y)(6+2y)+12x+36y.\] Thay \(x=4/y\): \[F/T=4y^2+48y+72/y+8.\]`,r`Đạo hàm \(8y+48-72/y^2=0\iff8y^3+48y^2-72=0\). Đạo hàm bậc hai \(8+144/y^3>0\), nên có duy nhất một điểm min.`,r`Giải số nghiệm dương \(y\approx1.123983\). Suy ra \(x=4/y\approx3.55877\), làm tròn 3,56 cm.`],{unit:'cm'});
short(96,'opt',r`Gấp tờ giấy chữ nhật rộng 20 cm như hình, góc trên của nếp gấp là \(\alpha=\widehat{PNC}\). Chứng minh được độ dài nếp gấp \(L=\frac{c}{a\sin^3\alpha+b\sin\alpha}\), với a,b,c nguyên, \(0<c<20\). Tính \(2a+12b^2+c^3\).`,1010,'1010',[r`Khi gấp, hai tam giác MNP và CNP bằng nhau. Kẻ \(MH\perp BC\), có \(MH=20\), \(\widehat{MNH}=2\alpha\).`,r`Trong tam giác vuông MNH: \(MN=20/\sin2\alpha\). Trong tam giác vuông MNP có cạnh huyền NP: \(\cos\alpha=MN/NP\).`,r`\[L=NP=\frac{20}{\cos\alpha\sin2\alpha}=\frac{10}{\sin\alpha\cos^2\alpha}=\frac{10}{\sin\alpha-\sin^3\alpha}.\]`,r`Suy ra \(a=-1,b=1,c=10\). Biểu thức bằng \(2(-1)+12\cdot1^2+10^3=1010\).`],{tolerance:0});
short(97,'opt',r`Cá sấu thứ nhất dài \(L_1(t)=3-a3^{-kt}\) m trong 12 tháng, lúc đầu dài 1,8 m và sau 10 tháng dài 2,6 m. Con thứ hai có \(L_2(t)=2.5-3^{-0.2t}\). Chênh lệch chiều dài nhỏ nhất trên \([0;12]\) bằng bao nhiêu cm, làm tròn đến hàng phần mười?`,14,r`\(14.0\) cm`,[r`\(L_1(0)=1.8\Rightarrow a=1.2\). Từ \(L_1(10)=2.6\): \(1.2\cdot3^{-10k}=0.4\Rightarrow3^{-10k}=1/3\Rightarrow k=0.1\).`,r`Đặt \(u=3^{-0.1t}\), thì \(3^{-1.2}\le u\le1\). Chênh lệch \[|L_1-L_2|=|u^2-1.2u+0.5|.\]`,r`Hoàn thành bình phương: \(u^2-1.2u+0.5=(u-0.6)^2+0.14>0\). Giá trị 0,6 nằm trong miền của u.`,r`Chênh lệch nhỏ nhất 0,14 m = 14,0 cm, đạt khi \(3^{-0.1t}=0.6\).`],{unit:'cm'});
short(98,'opt',r`Thuyền ở A cách bờ thẳng một khoảng \(AB=5\) km. Kho C trên bờ cách B 7 km. Người chèo từ A đến M trên đoạn BC với tốc độ 1,2 m/s rồi đi bộ từ M đến C với tốc độ 1,8 m/s. BM bằng bao nhiêu km để đến kho nhanh nhất? Có thể nhập biểu thức chính xác hoặc kết quả làm tròn đến hàng phần trăm.`,2*Math.sqrt(5),r`\(BM=2\sqrt5\approx4.47\) km`,[r`Đổi tốc độ: 1,2 m/s = 4,32 km/h; 1,8 m/s = 6,48 km/h. Đặt \(x=BM\in[0;7]\).`,r`\[T(x)=\frac{\sqrt{x^2+25}}{4.32}+\frac{7-x}{6.48},\quad T'(x)=\frac{x}{4.32\sqrt{x^2+25}}-\frac1{6.48}.\]`,r`\(T'=0\iff1.5x=\sqrt{x^2+25}\). Vì \(x\ge0\), bình phương được \(2.25x^2=x^2+25\Rightarrow x^2=20\Rightarrow x=2\sqrt5\).`,r`Đạo hàm âm trước nghiệm, dương sau nghiệm; nghiệm thuộc đoạn. Vậy \(BM=2\sqrt5\approx4.47\) km.`],{unit:'km',tolerance:0.005});
short(99,'opt',r`Lon nước hình trụ kín có thể tích 350 cm³. Tấm kim loại mặt bên không lãng phí, nhưng mỗi đáy tròn phải cắt từ một hình vuông cạnh bằng đường kính và bỏ phần thừa. Tìm chiều cao lon để ít tốn vật liệu nhất, làm tròn đến hàng phần trăm (cm).`,8.97,r`\(h\approx8.97\) cm`,[r`Đặt bán kính \(r>0\), chiều cao \(h>0\). Thể tích \(\pi r^2h=350\Rightarrow h=350/(\pi r^2)\).`,r`Vật liệu gồm mặt bên và hai hình vuông cắt đáy: \[S=2\pi rh+2(2r)^2=700/r+8r^2.\]`,r`\(S'=-700/r^2+16r=0\iff r^3=175/4\). Đạo hàm âm trước nghiệm dương, dương sau nghiệm, nên đạt min tại \(r=\sqrt[3]{175/4}\).`,r`\[h=\frac{350}{\pi(\sqrt[3]{175/4})^2}\approx8.9729\text{ cm}.\] Làm tròn được 8,97 cm.`],{unit:'cm'});
short(100,'tangent',r`Một sân golf có đường cong BC là phần đồ thị \(f(x)=ax^3+bx^2+cx+d\), với \(B(-1;\frac92)\) là điểm uốn, \(C(1;4)\), \(D(\frac{25}9;0)\). Các đoạn AB, CD là tiếp tuyến tại B,C. Nếu \(A(p;0)\), tính \(p^4\).`,2401,r`\(p^4=2401\)`,[r`Có \(f(-1)=9/2\), \(f(1)=4\), \(f''(-1)=0\). Tiếp tuyến CD có hệ số góc \[\frac{0-4}{25/9-1}=-\frac94=f'(1).\]`,r`Vì \(f'=3ax^2+2bx+c\), \(f''=6ax+2b\), ta được \[-a+b-c+d=9/2,\quad a+b+c+d=4,\quad-6a+2b=0,\quad3a+2b+c=-9/4.\]`,r`Giải hệ: \(a=-1/4,b=-3/4,c=0,d=5\). Khi đó \(f'(-1)=3/4\); tiếp tuyến AB là \(y=\frac34(x+1)+9/2\).`,r`Cho \(y=0\): \(3(p+1)+18=0\Rightarrow p=-7\). Suy ra \(p^4=2401\).`],{tolerance:0});
short(101,'opt',r`Lều gồm phần trụ cao 5 m, bán kính r, phía trên là nón có đường sinh 9 m như hình. Tìm thể tích tối đa của lều, làm tròn đến hàng đơn vị (m³).`,1372,'1372 m³',[r`Gọi chiều cao nón là h, \(0<h<9\). Pythagore: \(r^2=81-h^2\).`,r`\[V(h)=5\pi r^2+\frac13\pi r^2h=\pi\left(405+27h-5h^2-\frac13h^3\right).\]`,r`\(V'/\pi=27-10h-h^2=0\Rightarrow h=-5\pm2\sqrt{13}\). Chỉ \(-5+2\sqrt{13}\) thuộc miền; đạo hàm dương trước và âm sau.`,r`Thay nghiệm vào V được khoảng 1371,78 m³. Làm tròn đến hàng đơn vị là 1372 m³.`],{unit:'m³',tolerance:0});
short(102,'opt',r`Cốc hình nón úp ngược cao 3 dm, bán kính miệng 4 dm, ban đầu đầy nước. Đặt một quả cầu sắt tiếp xúc mặt bên trong cốc như hình; cầu có thể nhô khỏi miệng cốc. Tìm thể tích nước tràn lớn nhất, làm tròn đến hàng phần mười (lít).`,42.8,r`\(\frac{2304\pi}{169}\approx42.8\) lít`,[r`Xét mặt cắt qua trục: tam giác vuông có hai cạnh 3,4, cạnh huyền 5. Nếu bán kính cầu là r, tâm nằm trên trục thì khoảng cách tâm tới đỉnh nón \(OI=5r/4\).`,r`Nếu cầu chìm hoàn toàn: \(OI+r\le3\Rightarrow r\le4/3\). Thể tích tối đa trường hợp này \(V_1=\frac43\pi(4/3)^3\approx9.93\) lít.`,r`Nếu cầu nhô lên: phần chìm là chỏm cầu cao \(H=3-r/4\), với \(4/3<r<12\). \[V_2=\pi H^2(r-H/3)=\frac\pi{192}(12-r)^2(13r-12).\]`,r`\[V'_2=\frac\pi{192}(12-r)(180-39r).\] Đổi dấu từ dương sang âm tại \(r=60/13\), nên \(V_{2,\max}=2304\pi/169\approx42.83\) lít.`,r`So sánh hai trường hợp: 42,83 lớn hơn 9,93. Nước tràn lớn nhất làm tròn là 42,8 lít.`],{unit:'lít'});
short(103,'opt',r`Hai điện trở song song thỏa \(1/R=1/R_1+1/R_2\). Lúc đầu \(R_1=120\Omega\) giảm a Ω/s, \(R_2=b\Omega\) tăng 0,5 Ω/s, \(R=40\Omega\) và \(R'=1/9\) Ω/s. Tìm tổng trở lớn nhất, làm tròn đến hàng phần mười (Ω).`,41.2,r`\(R_{\max}\approx41.2\ \Omega\)`,[r`Ban đầu \(1/40=1/120+1/b\Rightarrow b=60\).`,r`Lấy đạo hàm theo thời gian: \[-\frac{R'}{R^2}=-\frac{R'_1}{R_1^2}-\frac{R'_2}{R_2^2}.\] Thay \(R'_1=-a,R'_2=0.5\): \(-1/14400=a/14400-1/7200\Rightarrow a=1\).`,r`\(R_1=120-t\), \(R_2=60+0.5t\), miền \(0\le t<120\). Muốn max R thì min \(F=1/R=1/(120-t)+1/(60+0.5t)\).`,r`\[F'=\frac1{(120-t)^2}-\frac{0.5}{(60+0.5t)^2}=0\iff120-t=\sqrt2(60+0.5t).\] Suy ra \(t=360-240\sqrt2\approx20.59\), là điểm min của F.`,r`Thay thời điểm vào công thức R được khoảng 41,1775 Ω; làm tròn 41,2 Ω.`],{unit:'Ω'});
short(104,'opt',r`Silo không đáy gồm thân trụ và nắp nửa cầu. Chi phí nắp 100 nghìn đồng/m², thân trụ 75 nghìn đồng/m². Gạo chỉ chứa trong phần trụ, khối lượng 24 tấn, khối lượng riêng 1200 kg/m³. Bỏ qua độ dày, tìm chi phí xây dựng nhỏ nhất, làm tròn đến hàng phần trăm (triệu đồng).`,3.37,'3,37 triệu đồng',[r`Đổi 24 tấn = 24000 kg, thể tích gạo \(V=24000/1200=20\) m³. Đặt bán kính r, chiều cao thân h, \(\pi r^2h=20\).`,r`Chi phí theo nghìn đồng: \[C=100(2\pi r^2)+75(2\pi rh)=200\pi r^2+3000/r,\quad r>0.\]`,r`\(C'=400\pi r-3000/r^2=0\iff r^3=15/(2\pi)\). Đạo hàm âm trước nghiệm, dương sau nghiệm nên đó là min.`,r`\(r\approx1.3365\) m; \(C_{\min}\approx3366.99\) nghìn = 3,36699 triệu đồng. Làm tròn 3,37 triệu đồng.`],{unit:'triệu đồng'});
short(105,'tangent',r`Cung đường ray tàu lượn là một phần parabol nối hai đoạn thẳng có hệ số góc lần lượt 0,5 và −1; hai đoạn là tiếp tuyến tại A,B như hình. Đặt A ở gốc tọa độ, trục hoành nằm ngang; khoảng cách ngang giữa A,B là 100 m. Tính chênh lệch độ cao hai điểm (m).`,25,'25 m',[r`Viết parabol \(y=ax^2+bx+c\). Vì A(0;0) thuộc đồ thị, \(c=0\). Đạo hàm \(y'=2ax+b\).`,r`Tiếp tuyến tại A có hệ số góc 0,5 nên \(b=0.5\). Hoành độ B bằng 100, hệ số góc tại B là −1: \(200a+0.5=-1\Rightarrow a=-3/400\).`,r`\(y_B=(-3/400)\cdot100^2+0.5\cdot100=-75+50=-25\).`,r`Chênh lệch độ cao là \(|y_B-y_A|=|-25-0|=25\) m.`],{unit:'m',tolerance:0});

